165	  /**
166	   * Reads the top-level scalar keys of a SKILL.md YAML frontmatter block. Only `name` and `description` are used;
167	   * no other key (e.g. `allowed-tools`) has any effect. Supports plain, quoted, multi-line plain, and block
168	   * (`|`, `>`, with `-`/`+` chomping) scalars; nested mappings are skipped, never merged into the top level.
169	   */
170	  private parseFrontmatter(text: string): { metadata: Record<string, string>; body: string } {
171	    const lines = text.replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").trim().split("\n");
172	    if (lines[0]?.trim() !== "---") {
173	      return { metadata: {}, body: text };
174	    }
175	    const close = lines.findIndex((line, i) => i > 0 && line.trim() === "---");
176	    if (close === -1) {
177	      return { metadata: {}, body: text };
178	    }
179	
180	    const yamlLines = lines.slice(1, close);
181	    const body = lines.slice(close + 1).join("\n").trim();
182	    const metadata: Record<string, string> = {};
183	
184	    for (let i = 0; i < yamlLines.length; i++) {
185	      const match = /^([A-Za-z0-9_-]+):(?:\s+(.*))?$/.exec(yamlLines[i].trimEnd());
186	      if (!match) continue; // indented (nested or continuation) lines, comments, list items
187	      const key = match[1];
188	      let val = (match[2] ?? "").trim();
189	      const continuation: string[] = [];
190	      while (i + 1 < yamlLines.length && (/^\s/.test(yamlLines[i + 1]) || yamlLines[i + 1].trim() === "")) {
191	        continuation.push(yamlLines[++i]);
192	      }
193	      const block = /^([|>])([+-]?)$/.exec(val);
194	      if (block) {
195	        const indent = Math.min(...continuation.filter((l) => l.trim()).map((l) => l.length - l.trimStart().length));
196	        const content = continuation.map((l) => l.slice(Number.isFinite(indent) ? indent : 0).trimEnd());
197	        while (content.length && content[content.length - 1] === "") content.pop();
198	        val = block[1] === "|" ? content.join("\n") : content.join("\n").replace(/([^\n])\n(?=[^\n])/g, "$1 ");
199	      } else if (val === "" || !/^["'{[]/.test(val)) {
200	        val = [val, ...continuation.map((l) => l.trim())].filter(Boolean).join(" ");
201	      }
202	      if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
203	        val = val.slice(1, -1);
204	      }
205	      metadata[key] = val;
206	    }
207	
208	    return { metadata, body };
209	  }
