      const counted = sm.getPromptSection(500);
      assert.ok(counted.length <= 500, `catalog is ${counted.length} chars`);
      assert.match(counted, /…and \\d+ more \\(an unknown name passed to `activate_skill` lists them all\\)\\n$/);
    });
  });
});
